-- | module storing information on which ttf font should be used for which
-- character and fontstyle
module MegaFont where

import BaseFont

-- | map (written as list) storing information on which ttf font should be used
-- for which character and fontstyle
megafont :: [(FontStyle, [Char])]
megafont = [(FontStyle {stylebase = Normal, bold = False, italic = False}, ""), (FontStyle {stylebase = Normal, bold = True, italic = False}, ""), (FontStyle {stylebase = Normal, bold = False, italic = True}, ""), (FontStyle {stylebase = Normal, bold = True, italic = True}, ""), (FontStyle {stylebase = Mono, bold = False, italic = False}, ""), (FontStyle {stylebase = Mono, bold = True, italic = False}, ""), (FontStyle {stylebase = Mono, bold = False, italic = True}, ""), (FontStyle {stylebase = Mono, bold = True, italic = True}, ""), (FontStyle {stylebase = Smallcaps, bold = False, italic = False}, ""), (FontStyle {stylebase = Smallcaps, bold = True, italic = False}, ""), (FontStyle {stylebase = Smallcaps, bold = False, italic = True}, ""), (FontStyle {stylebase = Smallcaps, bold = True, italic = True}, "")]
